"""
patch_finetune.py — One-shot hardening of finetune/generated:
  1. Expand 5 low-coverage entities to ≥40 rows
  2. Create MOBILE_OPERATOR.jsonl (40 rows)
  3. Cap confidence=1.0 rows to 0.97
  4. Add 8 low-severity (MEDIUM/LOW) CD rows
  5. Fill the 6 rows with empty location_mentions
"""
import json, os, pathlib

ROOT = pathlib.Path(__file__).parent / "generated"

# ---------------------------------------------------------------------------
# helpers
# ---------------------------------------------------------------------------

def load(entity):
    p = ROOT / f"{entity}.jsonl"
    if not p.exists():
        return []
    return [json.loads(l) for l in p.read_text(encoding="utf-8").splitlines() if l.strip()]

def save(entity, rows):
    p = ROOT / f"{entity}.jsonl"
    p.write_text("\n".join(json.dumps(r, ensure_ascii=False) for r in rows) + "\n", encoding="utf-8")
    print(f"  {entity:<25} {len(rows):>4} rows  -> saved")

def r(is_complaint, eng, issue_type, category, subcategory, severity, locations,
       keywords, summary, pub_safety, traffic, corruption, emergency,
       domain, component, failure_mode, hazard_type, public_space, requires_emerg,
       text_ev, missing_info, vis_hazard, objects, actions, loc_ctx, confidence):
    return {
        "is_complaint": is_complaint,
        "english_translation": eng,
        "issue_type": issue_type,
        "category": category,
        "subcategory": subcategory,
        "severity": severity,
        "location_mentions": locations,
        "keywords": keywords,
        "summary": summary,
        "signals": {
            "public_safety_risk": pub_safety,
            "traffic_impact": traffic,
            "corruption_signal": corruption,
            "emergency_signal": emergency,
        },
        "routing_features": {
            "domain": domain,
            "physical_component": component,
            "failure_mode": failure_mode,
            "hazard_type": hazard_type,
            "affected_public_space": public_space,
            "requires_emergency_attention": requires_emerg,
        },
        "evidence": {
            "text_evidence": text_ev,
            "image_evidence": [],
            "missing_information": missing_info,
        },
        "alignment_features": {
            "domain": domain,
            "physical_component": component,
            "failure_mode": failure_mode,
            "visible_hazard": vis_hazard,
            "objects": objects,
            "actions": actions,
            "location_context": loc_ctx,
        },
        "confidence": confidence,
        "semantic_domain": domain,
        "physical_component": component,
        "failure_mode": failure_mode,
    }


