# ============================================================
# Apply all changes
# ============================================================
print("\n=== Expanding low-coverage entities ===")
for entity, new_rows in [("DGLAC",DGLAC_NEW),("LRA",LRA_NEW),("TRA",TRA_NEW),("CENTRAL_INSPECTION",CI_NEW),("MUNICIPAL_POLICE",MP_NEW)]:
    rows = load(entity) + new_rows
    save(entity, rows)

print("\n=== Creating MOBILE_OPERATOR ===")
save("MOBILE_OPERATOR", MOB_NEW)

print("\n=== Capping confidence=1.0 to 0.97 ===")
capped = 0
for fn in sorted(ROOT.glob("*.jsonl")):
    rows = [json.loads(l) for l in fn.read_text(encoding="utf-8").splitlines() if l.strip()]
    changed = False
    for row in rows:
        if row.get("confidence", 0) >= 1.0:
            row["confidence"] = 0.97
            capped += 1
            changed = True
    if changed:
        fn.write_text("\n".join(json.dumps(r, ensure_ascii=False) for r in rows) + "\n", encoding="utf-8")
print(f"  Capped {capped} rows to 0.97")

print("\n=== Adding low-severity CD rows ===")
rows = load("CD") + CD_LOW
save("CD", rows)

print("\n=== Fixing empty location_mentions ===")
fixed = 0
LOCATION_FIXES = {
    # We'll scan all files and fill empty location lists with a derived location
    # based on routing context available in the row itself
}
for fn in sorted(ROOT.glob("*.jsonl")):
    rows = [json.loads(l) for l in fn.read_text(encoding="utf-8").splitlines() if l.strip()]
    changed = False
    for row in rows:
        lm = row.get("location_mentions", [])
        if not lm:
            # Derive from loc_ctx in alignment_features
            loc_ctx = (row.get("alignment_features") or {}).get("location_context", [])
            if loc_ctx:
                row["location_mentions"] = [lc.replace("_", " ").title() for lc in loc_ctx if lc]
                fixed += 1
                changed = True
            else:
                # fallback: use entity domain to set Lebanon generic
                row["location_mentions"] = ["Lebanon"]
                fixed += 1
                changed = True
    if changed:
        fn.write_text("\n".join(json.dumps(r, ensure_ascii=False) for r in rows) + "\n", encoding="utf-8")
print(f"  Fixed {fixed} empty location_mentions rows")

print("\n=== Final row counts ===")
total = 0
for fn in sorted(ROOT.glob("*.jsonl")):
    n = sum(1 for l in fn.read_text(encoding="utf-8").splitlines() if l.strip())
    total += n
    flag = "  <-- LOW" if n < 40 else ""
    print(f"  {fn.stem:<25} {n:>4}{flag}")
print(f"\n  TOTAL: {total} rows across {len(list(ROOT.glob('*.jsonl')))} files")
